#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generate Stellar Mall AI Interview PDF - 追问篇（深水区五问）
基于 rag-backend 实际代码整理的面试应答稿，可溯源，不虚报。
"""

from fpdf import FPDF
import os

OUTPUT_PATH = r"D:\Desktop\stellar-mall\Stellar_Mall_AI_面试题_追问篇.pdf"
FONT_PATH = r"C:\Windows\Fonts\msyh.ttc"


class InterviewPDF(FPDF):
    def __init__(self):
        super().__init__()
        self.set_auto_page_break(auto=True, margin=20)
        self.add_font("YaHei", "", FONT_PATH)
        self.add_font("YaHei", "B", FONT_PATH)

    def header(self):
        if self.page_no() > 1:
            self.set_font("YaHei", "", 8)
            self.set_text_color(120, 120, 120)
            self.cell(0, 8, "Stellar Mall AI \u9762\u8bd5\u9898 \u00b7 \u8ffd\u95ee\u7bc7", align="L")
            self.cell(0, 8, f"\u7b2c {self.page_no()} \u9875", align="R", new_x="LMARGIN", new_y="NEXT")
            self.line(10, 14, 200, 14)
            self.ln(4)

    def footer(self):
        if self.page_no() > 1:
            self.set_y(-15)
            self.set_font("YaHei", "", 7)
            self.set_text_color(160, 160, 160)
            self.cell(0, 10, "Generated on 2026-08-05 | Stellar Mall Project - rag-backend", align="C")

    def cover_page(self):
        self.add_page()
        self.ln(45)
        self.set_font("YaHei", "B", 26)
        self.set_text_color(30, 60, 114)
        self.cell(0, 14, "Stellar Mall AI \u9762\u8bd5\u9898 \u00b7 \u8ffd\u95ee\u7bc7", align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(4)
        self.set_font("YaHei", "", 16)
        self.set_text_color(50, 100, 150)
        self.cell(0, 10, "\u6df1\u6c34\u533a\u4e94\u95ee\uff1a\u68c0\u7d22 / \u72b6\u6001\u673a / \u5411\u91cf\u5e93 / \u9632\u5e7b\u89c9 / \u9650\u6d41", align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(8)
        self.set_draw_color(30, 60, 114)
        self.set_line_width(0.5)
        mid = 105
        self.line(mid - 50, self.get_y(), mid + 50, self.get_y())
        self.ln(12)
        self.set_font("YaHei", "", 10.5)
        self.set_text_color(80, 80, 80)
        lines = [
            "\u6bcf\u9898\u542b\u4e09\u90e8\u5206\uff1a\u5e94\u7b54\u7a3f + \u8ffd\u95ee\u70b9\u51c6\u5907 + \u4ee3\u7801\u6eaf\u6e90",
            "\u54cd\u5e94\u4ee5 rag-backend \u5b9e\u9645\u5b9e\u73b0\u4e3a\u51c6\uff0c\u672a\u5b9e\u73b0\u7684\u65b9\u6848\u5747\u6807\u6ce8\u201c\u6f14\u8fdb\u65b9\u5411\u201d",
            "\u5b8c\u6574\u4e94\u9898\uff0c\u4e13\u6ce8\u201c\u9762\u8bd5\u5b98\u8ffd\u95ee\u4e0b\u53bb\u4f1a\u7a7f\u5e2e\u201d\u7684\u7ec6\u8282",
        ]
        for line in lines:
            self.cell(0, 8, line, align="C", new_x="LMARGIN", new_y="NEXT")
        self.ln(16)
        self.set_font("YaHei", "", 9)
        self.set_text_color(140, 140, 140)
        self.cell(0, 8, "Stellar Mall Project - rag-backend \uff08\u4e0e\u300a\u9762\u8bd5\u9898\u300b\u4e3b\u5377\u914d\u5957\u4f7f\u7528\uff09", align="C", new_x="LMARGIN", new_y="NEXT")

    def section_title(self, title):
        self.set_font("YaHei", "B", 13)
        self.set_text_color(30, 60, 114)
        self.ln(5)
        self.cell(0, 9, title, new_x="LMARGIN", new_y="NEXT")
        self.set_draw_color(30, 60, 114)
        self.set_line_width(0.4)
        self.line(10, self.get_y(), 200, self.get_y())
        self.ln(3)

    def question(self, q_num, text):
        self.set_font("YaHei", "B", 10)
        self.set_text_color(30, 60, 114)
        self.set_x(12)
        self.cell(0, 7, f"[{q_num}] (\u6df1\u6c34\u533a)", new_x="LMARGIN", new_y="NEXT")
        self.set_x(18)
        self.set_font("YaHei", "", 9.5)
        self.set_text_color(30, 30, 30)
        self.multi_cell(182, 6.5, text)
        self.ln(2)

    def block(self, label, text, color=(200, 60, 60)):
        self.set_font("YaHei", "B", 9.5)
        self.set_text_color(*color)
        self.set_x(12)
        self.cell(0, 7, f"\u2192 {label}", new_x="LMARGIN", new_y="NEXT")
        self.set_font("YaHei", "", 9)
        self.set_text_color(40, 40, 40)
        self.set_x(18)
        self.multi_cell(182, 5.5, text)
        self.ln(2)


def build_pdf():
    pdf = InterviewPDF()
    pdf.set_margins(12, 12, 12)

    pdf.cover_page()

    # ================= Q1 =================
    pdf.add_page()
    pdf.section_title("\u4e00\u3001\u6df7\u5408\u56de\u6536\u4e0e\u878d\u5408\u6743\u91cd")
